<js>
var matcher = String(result).match(/(\d+)\/(\d+)/);
var id= parseInt(matcher ? matcher[1] : 0);
var len= parseInt(matcher ? matcher[2] : 0);
var pages = [];
for(var i=2;i<=len;i++) pages.push('/novel/'+id+'/'+i+'/asc');
pages
